    56→
    57→LIGHTING: Bright front-facing softbox, high-key lighting to eliminate all shadows on backdrop.
    58→
    59→OUTPUT: E-commerce product photo quality, clean cutout-ready image.
    60→`.trim();
    61→
    62→/**
    63→ * Mystery mode prompt template for users who don't upload photos
    64→ * Shortened to stay under 1000 character limit for outfit generation
    65→ */
    66→const MYSTERY_MODEL_PROMPT = `
    67→E-commerce fashion catalog photo of Thai woman, 25-30, natural beauty, warm brown eyes, shoulder-length black hair.
    68→
    69→OUTFIT: White spaghetti strap crop top, black high-waisted legging shorts, barefoot.
    70→
    71→POSE: Standing straight, facing camera, arms at sides, feet together.
    72→
    73→MANDATORY BACKGROUND: Pure white infinity cove (RGB 255,255,255). Model floats in infinite white void - NO floor, NO ground, NO shadows on backdrop.
    74→
    75→LIGHTING: High-key softbox, bright even illumination eliminating all backdrop shadows.
    76→
    77→OUTPUT: Clean cutout-ready product photo.
    78→`.trim();
    79→
    80→/**
    81→ * Generates a fitting model image from the user's photo
    82→ *
    83→ * @param userPhotoBase64 - Base64 encoded user photo (with data URL prefix)
    84→ * @returns Promise resolving to fitting model response
    85→ */
    86→export async function generateFittingModel(
    87→  userPhotoBase64: string
    88→): Promise<FittingModelResponse> {
    89→  try {
    90→    console.log('[FittingModel] Generating fitting model from user photo');
    91→
    92→    // Call the image generation API with reference image for multimodal generation
    93→    const response = await fetch('/api/generate-image', {
    94→      method: 'POST',
    95→      headers: {
    96→        'Content-Type': 'application/json',
    97→      },
    98→      body: JSON.stringify({
    99→        description: FITTING_MODEL_PROMPT_TEMPLATE,
   100→        referenceImage: userPhotoBase64,
   101→        generationType: 'fitting-model',
   102→        style: {
   103→          photographyStyle: 'professional studio',
   104→          composition: 'full-body frontal shot',
   105→          lighting: 'soft studio',
   106→          aestheticContext: 'clean minimal fashion',
   107→        },
   108→      }),
   109→    });
   110→
   111→    const data = await response.json();
   112→
   113→    if (!response.ok) {
   114→      console.error('[FittingModel] API error:', data);
   115→      return {
   116→        success: false,
   117→        error: data.error || 'GENERATION_FAILED',
   118→        message: data.message || 'Failed to generate fitting model',
   119→      };
   120→    }
   121→
   122→    if (data.success) {
   123→      console.log('[FittingModel] Generation successful');
   124→      return {
   125→        success: true,
   126→        imageUrl: data.imageUrl,
   127→        imageBase64: data.imageBase64,
   128→        message: 'Fitting model generated successfully',
   129→      };
   130→    }
   131→
   132→    return {
   133→      success: false,
   134→      error: data.error || 'GENERATION_FAILED',
   135→      message: data.message || 'Failed to generate fitting model',
   136→    };
   137→  } catch (error) {
   138→    console.error('[FittingModel] Error generating fitting model:', error);
   139→    return {
   140→      success: false,
   141→      error: 'NETWORK_ERROR',
   142→      message: 'Unable to connect to the image generation service',
   143→    };
   144→  }
   145→}
   146→
   147→/**
   148→ * Generates a default fitting model for "Mystery" option
   149→ * Creates an anonymous fitting model without a specific face reference
   150→ *
   151→ * @returns Promise resolving to fitting model response
   152→ */
   153→export async function generateDefaultFittingModel(): Promise<FittingModelResponse> {
   154→  try {
