'use client';

import { useState, useEffect } from 'react';
import { UserProfile, PartialUserProfile } from '@/lib/types/user-profile-types';

const STORAGE_KEY = 'ootday_user_profile';

/**
 * Custom hook for managing user profile state with localStorage persistence
 */
export function useUserProfile() {
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Load profile from localStorage on mount
  useEffect(() => {
    loadProfile();
  }, []);

  /**
   * Load user profile from localStorage
   */
  const loadProfile = () => {
    try {
      const storedProfile = localStorage.getItem(STORAGE_KEY);
      if (storedProfile) {
        const parsedProfile = JSON.parse(storedProfile) as UserProfile;
        setProfile(parsedProfile);
      }
    } catch (error) {
      console.error('Error loading user profile:', error);
    } finally {
      setIsLoading(false);
    }
  };

  /**
   * Save user profile to localStorage
   */
  const saveProfile = (profileData: UserProfile) => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(profileData));
      setProfile(profileData);
    } catch (error) {
      console.error('Error saving user profile:', error);
    }
  };

  /**
   * Update partial profile data (merge with existing)
   */
  const updateProfile = (updates: PartialUserProfile) => {
    const updatedProfile: UserProfile = {
      userName: updates.userName ?? profile?.userName ?? '',
      gender: updates.gender ?? profile?.gender ?? 'women', // v2.4: Fix - use updates.gender instead of hardcoded value
      ageRange: updates.ageRange ?? profile?.ageRange ?? '<20',
      stylePreferences: updates.stylePreferences ?? profile?.stylePreferences ?? [],
      userPhoto: updates.userPhoto ?? profile?.userPhoto,
      fittingModelUrl: updates.fittingModelUrl ?? profile?.fittingModelUrl,
      onboardingCompleted: updates.onboardingCompleted ?? profile?.onboardingCompleted ?? false,
      createdAt: profile?.createdAt ?? new Date().toISOString(),
    };
    saveProfile(updatedProfile);
  };

  /**
   * Mark onboarding as complete
   */
  const completeOnboarding = () => {
    if (profile) {
      const completedProfile: UserProfile = {
        ...profile,
        onboardingCompleted: true,
      };
      saveProfile(completedProfile);
    }
  };

  /**
   * Clear profile and reset onboarding (for testing)
   */
  const clearProfile = () => {
    try {
      localStorage.removeItem(STORAGE_KEY);
      setProfile(null);
    } catch (error) {
      console.error('Error clearing user profile:', error);
    }
  };

  return {
    profile,
    isLoading,
    loadProfile,
    saveProfile,
    updateProfile,
    completeOnboarding,
    clearProfile,
  };
}

// TypeScript interfaces for OOTDay Fashion Assistant

// Export all new type definitions
export * from './types/enums'
export * from './types/localization-types'
export * from './types/product-types'

// Re-export FlatLayItem from image-types for use in ChatMessage
import type { FlatLayItem } from './types/image-types'
export type { FlatLayItem }

// Legacy interfaces maintained for backward compatibility
// These will gradually be replaced by EnhancedProduct
export interface OutfitRequest {
  query: string
  userId?: string
  context?: {
    occasion?: string
    weather?: string
    preferences?: string[]
  }
}

export interface OutfitResponse {
  outfits: Outfit[]
  conversationId: string
  suggestions: string[]
}

export interface Outfit {
  id: string
  title: string
  description: string
  totalPrice: number
  items: Product[]
  imageUrl?: string
  /** Flat-lay image URL for outfit visualization (v5.0) */
  flatLayImageUrl?: string
  /** Flat-lay image as base64 fallback (v5.0) */
  flatLayImageBase64?: string
  /** Flag indicating flat-lay image is being generated (v5.0) */
  isGeneratingFlatLay?: boolean
  /** Try-on image URL for fitting model visualization (v6.0) */
  tryOnImageUrl?: string
  /** Try-on image as base64 fallback (v6.0) */
  tryOnImageBase64?: string
  /** Flag indicating try-on image is being generated (v6.0) */
  isGeneratingTryOn?: boolean
}

/**
 * @deprecated Use EnhancedProduct from './types/product-types' instead
 * This interface is kept for backward compatibility
 */
export interface Product {
  sku: string
  name: string
  brand: string
  price: number
  imageUrl: string
  availability: "in_stock" | "low_stock" | "out_of_stock"
  storeLocations?: string[]
  onlineUrl?: string
  sizes?: string[]
  colors?: string[]
  category?: string // "Men", "Women", or other categories
  subCategory?: string // "Blazer", "Skirt", "Pants", etc.
  visualDescription?: string // For AI Image Generation prompt
  occasion?: string[] // For filtering
}

export interface ChatMessage {
  id: string
  content: string
  sender: "user" | "assistant"
  timestamp: Date
  outfits?: Outfit[]
  /** Image URL for generated outfit visualization (v3.1) */
  imageUrl?: string
  /** Base64-encoded image data (v3.1) */
  imageBase64?: string
  /** Outfit description used for image generation (v3.1) */
  outfitDescription?: string
  /** Image display mode: 'portrait' (3:4) or 'flat-lay' (1:1 square) (v4.0) */
  displayMode?: 'portrait' | 'flat-lay'
  /** Recommended items for flat-lay display (v4.0) */
  recommendedItems?: FlatLayItem[]
}

export interface ConversationStarter {
  id: string
  text: string
  category: string
}

export interface FilterState {
  gender?: 'all' | 'men' | 'women'
  occasion?: string[]  // ['work', 'casual', 'date', 'formal']
  priceRange?: { min: number; max: number }
  searchQuery?: string
}
